from datetime import datetime
from airflow.decorators import dag, task

@dag(
    dag_id='taskflow_etl',
    schedule='@daily',
    start_date=datetime(2024, 1, 1),
    catchup=False,
    tags=['taskflow'],
)
def taskflow_etl():

    @task
    def extract() -> dict:
        return {'records': [1, 2, 3, 4, 5]}

    @task
    def transform(data: dict) -> int:
        return sum(data['records'])

    @task
    def load(total: int) -> None:
        print(f"Loaded total = {total}")

    # dependencies are inferred from how outputs feed inputs
    total = transform(extract())
    load(total)

dag_instance = taskflow_etl()
